#include <algorithm>
#include <cstdio>
#include <iostream>
#include <numeric>
#include <vector>

struct Boot { int depth, stride, index; };

int main() {
    std::freopen("snowboots.in", "r", stdin);
    std::freopen("snowboots.out", "w", stdout);
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    int n, b;
    if (!(std::cin >> n >> b)) return 0;
    std::vector<int> snow(n);
    for (int& x : snow) std::cin >> x;
    std::vector<Boot> boots(b);
    for (int i = 0; i < b; ++i) {
        std::cin >> boots[i].depth >> boots[i].stride;
        boots[i].index = i;
    }
    std::vector<int> answer(b, 1);
    if (n > 1) {
        std::vector<int> tiles;
        for (int i = 1; i + 1 < n; ++i) tiles.push_back(i);
        std::sort(tiles.begin(), tiles.end(), [&](int x, int y) {
            return snow[x] > snow[y];
        });
        std::sort(boots.begin(), boots.end(), [](const Boot& x, const Boot& y) {
            return x.depth > y.depth;
        });
        std::vector<int> before(n), after(n);
        for (int i = 0; i < n; ++i) {
            before[i] = i - 1;
            after[i] = i + 1;
        }
        int largest_gap = 1;
        std::size_t removed = 0;
        for (const Boot& boot : boots) {
            while (removed < tiles.size() && snow[tiles[removed]] > boot.depth) {
                const int tile = tiles[removed++];
                const int left = before[tile], right = after[tile];
                after[left] = right;
                before[right] = left;
                largest_gap = std::max(largest_gap, right - left);
            }
            answer[boot.index] = boot.stride >= largest_gap;
        }
    }
    for (int x : answer) std::cout << x << '\n';
    return 0;
}
