int main() {
    std::freopen("dirtraverse.in", "r", stdin);
    std::freopen("dirtraverse.out", "w", stdout);
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    int n;
    if (!(std::cin >> n)) return 0;
    std::vector<std::vector<int>> child(n);
    std::vector<int> length(n);
    for (int i = 0; i < n; ++i) {
        std::string name;
        int count;
        std::cin >> name >> count;
        length[i] = static_cast<int>(name.size());
        child[i].resize(count);
        for (int& id : child[i]) { std::cin >> id; --id; }
    }
    std::vector<int> order{0};
    for (std::size_t i = 0; i < order.size(); ++i) {
        for (int v : child[order[i]]) order.push_back(v);
    }
    std::vector<long long> file_count(n, 0), downward(n, 0), total(n, 0);
    for (auto it = order.rbegin(); it != order.rend(); ++it) {
        const int u = *it;
        if (child[u].empty()) {
            file_count[u] = 1;
        } else {
            for (int v : child[u]) {
                const long long prefix = length[v] + (child[v].empty() ? 0 : 1);
                file_count[u] += file_count[v];
                downward[u] += downward[v] + prefix * file_count[v];
            }
        }
    }
    total[0] = downward[0];
    long long answer = total[0];
    const long long all_files = file_count[0];
    for (int u : order) {
        if (child[u].empty()) continue;
        answer = std::min(answer, total[u]);
        for (int v : child[u]) {
            if (!child[v].empty()) {
                total[v] = total[u]
                    - static_cast<long long>(length[v] + 1) * file_count[v]
                    + 3 * (all_files - file_count[v]);
            }
        }
    }
    std::cout << answer << '\n';
    return 0;
}
