#include <algorithm>
#include <cstdio>
#include <iostream>
#include <vector>

int main() {
    std::freopen("taming.in", "r", stdin);
    std::freopen("taming.out", "w", stdout);
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    int n;
    if (!(std::cin >> n)) return 0;
    std::vector<int> observed(n);
    for (int& x : observed) std::cin >> x;
    std::vector<std::vector<int>> changed(n, std::vector<int>(n, 0));
    for (int start = 0; start < n; ++start) {
        int errors = 0;
        for (int end = start; end < n; ++end) {
            errors += observed[end] != end - start;
            changed[start][end] = errors;
        }
    }
    constexpr int infinity = 1000000;
    std::vector<int> previous(n + 1, infinity);
    previous[0] = 0;
    for (int breakouts = 1; breakouts <= n; ++breakouts) {
        std::vector<int> current(n + 1, infinity);
        for (int days = breakouts; days <= n; ++days) {
            for (int split = breakouts - 1; split < days; ++split) {
                if (previous[split] != infinity) {
                    current[days] = std::min(current[days],
                        previous[split] + changed[split][days - 1]);
                }
            }
        }
        std::cout << current[n] << '\n';
        previous.swap(current);
    }
    return 0;
}
